# ── Otomatik DB Migration ──────────────────────────────────────────────────
# Sunucu her basladiginda eksik kolonlari ekler — mevcut kolonlara dokunmaz.
def _run_auto_migrations():
    col_migrations = [
        "ALTER TABLE clients ADD COLUMN disp_osd_json      TEXT    DEFAULT '{}'",
        "ALTER TABLE clients ADD COLUMN disp_reported_at   TEXT    DEFAULT ''",
        "ALTER TABLE clients ADD COLUMN disp_monitor_names TEXT    DEFAULT '[]'",
        "ALTER TABLE clients ADD COLUMN monitor_profile_id INTEGER DEFAULT NULL",
        "ALTER TABLE clients ADD COLUMN pending_monitor_apply INTEGER DEFAULT 0",
    ]
    table_migrations = [
        """CREATE TABLE IF NOT EXISTS mklink_templates (
            id      INTEGER PRIMARY KEY AUTOINCREMENT,
            name    TEXT NOT NULL,
            description TEXT DEFAULT ''
        )""",
        """CREATE TABLE IF NOT EXISTS mklink_template_items (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            template_id INTEGER NOT NULL REFERENCES mklink_templates(id) ON DELETE CASCADE,
            source      TEXT NOT NULL,
            target      TEXT NOT NULL,
            link_type   TEXT DEFAULT 'J'
        )""",
        """CREATE TABLE IF NOT EXISTS monitor_profiles (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            name            TEXT NOT NULL,
            osd_json        TEXT DEFAULT '{}',
            osd_labels      TEXT DEFAULT '{}',
            source_hostname TEXT DEFAULT '',
            created_at      TEXT DEFAULT ''
        )""",
        """CREATE TABLE IF NOT EXISTS monitor_apply_log (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            hostname    TEXT,
            profile_id  INTEGER,
            action      TEXT,
            created_at  TEXT DEFAULT (datetime('now','localtime'))
        )""",
    ]
    try:
        with db.get_connection() as conn:
            for sql in col_migrations:
                try:
                    conn.execute(sql)
                    conn.commit()
                except Exception:
                    pass
            for sql in table_migrations:
                try:
                    conn.execute(sql)
                    conn.commit()
                except Exception:
                    pass
    except Exception as e:
        logging.getLogger('gameserver').warning(f"Auto-migration hatasi: {e}")

_run_auto_migrations()
