@app.after_request
def add_cache_headers(response):
    if request.path.startswith('/api/'):
        response.headers['Cache-Control'] = 'no-store, no-cache, must-revalidate, max-age=0'
        response.headers['Pragma'] = 'no-cache'
        response.headers['Expires'] = '-1'
    return response

@app.before_request
def check_admin_ip():
    # Only restrict access to web admin panel paths and critical APIs.
    # We allow /api/games, /api/auth, /api/clients to keep GameCenterClient working.
    
    # Do not restrict static covers/icons
    if request.path.startswith("/covers/") or request.path.startswith("/api/icons/"):
        return
        
    # Allow client to read settings (required for GameCenterClient to start)
    if request.path == "/api/settings" and request.method == "GET":
        return
        
    if request.path.startswith("/api/settings") or request.path.startswith("/api/admin") or not request.path.startswith("/api/"):
            
        allowed_ips_str = db.get_setting("admin_allowed_ips", "").strip()
        if not allowed_ips_str:
            return
            
        client_ip = request.remote_addr
        if client_ip in ("127.0.0.1", "::1"):
            return
            
        allowed_ips = [ip.strip() for ip in allowed_ips_str.split(",") if ip.strip()]
        is_allowed = False
        try:
            client_ip_obj = ipaddress.ip_address(client_ip)
            for allowed_net in allowed_ips:
                if "/" in allowed_net:
                    if client_ip_obj in ipaddress.ip_network(allowed_net, strict=False):
                        is_allowed = True
                        break
                else:
                    if client_ip_obj == ipaddress.ip_address(allowed_net):
                        is_allowed = True
                        break
        except ValueError:
            pass
            
        if not is_allowed:
            return "EriÃƒâ€¦Ã…Â¸im Reddedildi: IP adresiniz bu sayfaya veya isleme erisim yetkisine sahip degil.", 403

# --- Thread-safe komut kÃƒÆ’Ã‚Â¼mesi ---
pending_commands = {}
_commands_lock = threading.Lock()

def cmd_push(hostname: str, command: dict):
    """Bir client iÃƒÆ’Ã‚Â§in kuyruÃƒâ€Ã…Â¸a komut ekler (thread-safe)."""
    with _commands_lock:
        if hostname not in pending_commands:
            pending_commands[hostname] = []
        pending_commands[hostname].append(command)

def cmd_pop_all(hostname: str) -> list:
    """Bir client'Ãƒâ€Ã‚Â±n tÃƒÆ’Ã‚Â¼m bekleyen komutlarÃƒâ€Ã‚Â±nÃƒâ€Ã‚Â± alÃƒâ€Ã‚Â±r ve kuyruÃƒâ€Ã…Â¸u temizler (thread-safe)."""
    with _commands_lock:
        return pending_commands.pop(hostname, [])

