@app.route("/api/system/hwid", methods=["GET"])
def get_system_hwid():
    import subprocess
    import uuid
    try:
        hwid = subprocess.check_output(['powershell', '-Command', '(Get-CimInstance -Class Win32_ComputerSystemProduct).UUID'], timeout=5).decode().strip()
        if not hwid or len(hwid) < 10:
            raise ValueError("Invalid HWID")
        return ok({"hwid": hwid})
    except Exception as e:
        # Fallback in case of an error
        return ok({"hwid": "HWID_ERROR_" + str(uuid.uuid4().hex[:8])})

@app.route("/api/auth/login", methods=["POST"])
@require_json
def auth_login():
    body = request.get_json()
    user = db.authenticate_user(body.get("username", ""), body.get("password", ""))
    if not user:
        return err("Kullanici adi veya sifre yanlis", 401)
        
    if body.get("admin_panel") and user.get("role") != "admin":
        logging.warning(f"Unauthorized login attempt by non-admin user: {user.get('username')}")
        return err("Bu panele sadece yÃƒÆ’Ã‚Â¶neticiler (admin) giriÃƒâ€¦Ã…Â¸ yapabilir", 403)
        
    user_data = dict(user)
    logging.info(f"Login OK: {user['username']} ({user['role']})")
    return ok(user_data)

@app.route("/api/auth/register", methods=["POST"])
@require_json
def auth_register():
    if db.get_setting("allow_register", "false") != "true":
        return err("Sunucu tarafindan kayit izni verilmemis", 403)
        
    body = request.get_json()
    username = body.get("username", "").strip()
    password = body.get("password", "")
    display_name = body.get("display_name", "").strip()
    
    if not display_name:
        return err("Isim soyisim bos olamaz", 400)
    if not username:
        return err("Kullanici adi bos olamaz", 400)
    if len(password) < 6:
        return err("Sifre en az 6 karakter olmalidir", 400)
        
    with db.get_connection() as conn:
        existing = conn.execute("SELECT id FROM users WHERE username=?", (username,)).fetchone()
        if existing:
            return err("Bu kullanici adi zaten alinmis", 400)
            
    uid = db.create_user(username, password, role="user", display_name=display_name, active=1)
    return ok({"id": uid}, status=201)

