@app.route("/api/games", methods=["GET"])
def games_list():
    active_only = request.args.get("active_only", "0") == "1"
    filtered    = request.args.get("filtered",    "0") == "1"
    hostname    = request.args.get("hostname",    None)
    games = db.get_all_games(active_only=active_only, filtered=filtered, hostname=hostname)
    return ok(games)

