@app.route("/api/clients/hw_summary", methods=["GET"])
def clients_hw_summary():
    """Web Admin iÃƒÆ’Ã‚Â§in: kafedeki mevcut GPU ve CPU modellerinin listesi (Plugin 8 UI)"""
    with db.get_connection() as conn:
        gpus = [r[0] for r in conn.execute(
            "SELECT DISTINCT gpu_model FROM clients WHERE gpu_model IS NOT NULL AND gpu_model != '' ORDER BY gpu_model"
        ).fetchall()]
        cpus = [r[0] for r in conn.execute(
            "SELECT DISTINCT cpu FROM clients WHERE cpu IS NOT NULL AND cpu != '' ORDER BY cpu"
        ).fetchall()]
        rams = sorted(set(
            int(r[0]) for r in conn.execute(
                "SELECT DISTINCT CAST(ram_total_gb AS INTEGER) FROM clients WHERE ram_total_gb IS NOT NULL AND ram_total_gb > 0"
            ).fetchall()
        ))
    return ok({"gpu": gpus, "cpu": cpus, "ram_sizes": rams})

