@app.route("/api/mklink_templates/wizard_batch", methods=["POST"])
@require_json
def mklink_wizard_batch():
    body = request.get_json()
    template_name = body.get("template_name", "").strip()
    mklink_base_path = body.get("mklink_base_path", "").strip()
    folders = body.get("folders", [])
    
    if not template_name:
        return err("Oyun/Ãƒâ€¦Ã‚Âablon adÃƒâ€Ã‚Â± gerekli")
    if not mklink_base_path:
        return err("Mklink dizini (hedef) gerekli")
    if not isinstance(folders, list) or len(folders) == 0:
        return err("En az bir klasÃƒÆ’Ã‚Â¶r kuralÃƒâ€Ã‚Â± gerekli")
        
    try:
        os.makedirs(mklink_base_path, exist_ok=True)
    except Exception as e:
        return err(f"Mklink ana dizini oluÃƒâ€¦Ã…Â¸turulamadÃƒâ€Ã‚Â±: {e}")
        
    # Ãƒâ€¦Ã‚Âablonu bul veya oluÃƒâ€¦Ã…Â¸tur
    templates = db.get_mklink_templates()
    t_id = None
    for t in templates:
        if t["name"].lower() == template_name.lower():
            t_id = t["id"]
            break
            
    if not t_id:
        t_id = db.create_mklink_template(template_name, "Sihirbaz ile oluÃƒâ€¦Ã…Â¸turuldu")
        
    results = []
    success_count = 0
    import shutil
    import subprocess
    import time
    
    for f in folders:
        source_abs = f.get("source_abs", "").strip()
        client_path = f.get("client_path", "").strip()
        server_category = f.get("server_category", "").strip()
        path_type = f.get("path_type", "static")
        
        if not source_abs or not os.path.isdir(source_abs):
            results.append({"source": source_abs, "status": "error", "error": "Kaynak klasÃƒÆ’Ã‚Â¶r bulunamadÃƒâ€Ã‚Â±"})
            continue
            
        # Kategori varsa hedef yola ekle
        target_base = mklink_base_path
        if server_category and server_category.lower() != "custom":
            target_base = os.path.join(mklink_base_path, server_category)
            os.makedirs(target_base, exist_ok=True)
            
        basename = os.path.basename(source_abs.rstrip("\\/"))
        dest_path = os.path.join(target_base, basename)
        
        if os.path.exists(dest_path):
            dest_path += f"_{int(time.time())}"
            
        try:
            # 1. KlasÃƒÆ’Ã‚Â¶rÃƒÆ’Ã‚Â¼ mklink klasÃƒÆ’Ã‚Â¶rÃƒÆ’Ã‚Â¼ne taÃƒâ€¦Ã…Â¸Ãƒâ€Ã‚Â±
            shutil.move(source_abs, dest_path)
            # 2. AsÃƒâ€Ã‚Â±l yerine mklink oluÃƒâ€¦Ã…Â¸tur ki sunucudaki oyun bozulmasÃƒâ€Ã‚Â±n
            subprocess.run(["cmd", "/c", "mklink", "/J", source_abs, dest_path], check=True)
            
            # 3. KuralÃƒâ€Ã‚Â± veritabanÃƒâ€Ã‚Â±na ekle
            i_id = db.add_mklink_template_item(t_id, dest_path, client_path, path_type)
            results.append({"source": source_abs, "status": "success", "dest": dest_path})
            success_count += 1
        except Exception as e:
            results.append({"source": source_abs, "status": "error", "error": str(e)})
            
    return ok({
        "message": f"{success_count} klasÃƒÆ’Ã‚Â¶r baÃƒâ€¦Ã…Â¸arÃƒâ€Ã‚Â±yla iÃƒâ€¦Ã…Â¸lendi",
        "results": results,
        "template_id": t_id
    })



@app.route("/api/github/search", methods=["GET"])
def github_search():
    import requests
    import re
    query = request.args.get("name", "").strip().lower()
    query_words = re.findall(r'[a-z0-9]+', query)
    
    url = "https://api.github.com/repos/rcpdkc/game-center-server/contents/contents/covers"
    try:
        r = requests.get(url, timeout=10)
        if r.status_code != 200:
            return err(f"GitHub API hatasÃƒâ€Ã‚Â±: {r.status_code}")
        items = r.json()
        if not isinstance(items, list):
            return err("GeÃƒÆ’Ã‚Â§ersiz API yanÃƒâ€Ã‚Â±tÃƒâ€Ã‚Â±")
        
        results = []
        for item in items:
            name = item.get("name", "")
            name_lower = name.lower()
            
            # EÃƒâ€¦Ã…Â¸leÃƒâ€¦Ã…Â¸me kontrolÃƒÆ’Ã‚Â¼: AranÃƒâ€Ã‚Â±lan kelimelerin tÃƒÆ’Ã‚Â¼mÃƒÆ’Ã‚Â¼ dosya isminin iÃƒÆ’Ã‚Â§inde var mÃƒâ€Ã‚Â±?
            match = True
            for word in query_words:
                if word not in name_lower:
                    match = False
                    break
                    
            if match or not query_words:
                results.append({
                    "name": name,
                    "download_url": item.get("download_url")
                })
        return ok({"covers": results})
    except Exception as e:
        return err(f"GitHub baÃƒâ€Ã…Â¸lantÃƒâ€Ã‚Â± hatasÃƒâ€Ã‚Â±: {str(e)}")

@app.route("/api/github/download", methods=["POST"])
@require_json
def github_download():
    import requests
    import os
    import time
    body = request.get_json()
    download_url = body.get("download_url")
    game_name = body.get("game_name", "game")
    
    if not download_url:
        return err("Eksik URL", 400)
    
    try:
        r = requests.get(download_url, timeout=15)
        if r.status_code != 200:
            return err(f"Ãƒâ€Ã‚Â°ndirme hatasÃƒâ€Ã‚Â±: {r.status_code}")
        
        ext = os.path.splitext(download_url)[1]
        if not ext or len(ext) > 5:
            ext = ".png"
            
        filename = "".join(c if c.isalnum() else "_" for c in game_name) + f"_{int(time.time())}{ext}"
        
        covers_dir = get_covers_dir()
        os.makedirs(covers_dir, exist_ok=True)
        local_path = os.path.join(covers_dir, filename)
        
        with open(local_path, "wb") as f:
            f.write(r.content)
            
        return ok({"local_path": f"/covers/{filename}"})
    except Exception as e:
        return err(f"Ãƒâ€Ã‚Â°ndirme hatasÃƒâ€Ã‚Â±: {str(e)}")

