@app.route("/api/genres/github_sync", methods=["POST"])
def genres_github_sync():
    import requests, unicodedata, shutil
    from _paths import get_data_dir
    
    url = "https://api.github.com/repos/rcpdkc/game-center-server/contents/contents/category"
    try:
        r = requests.get(url, headers={"User-Agent": "Mozilla/5.0"}, timeout=10)
        r.raise_for_status()
        files = r.json()
    except Exception as e:
        return err(f"GitHub baÃƒâ€Ã…Â¸lantÃƒâ€Ã‚Â± hatasÃƒâ€Ã‚Â±: {str(e)}")
        
    genres = db.get_all_genres()
    if not genres:
        return err("KayÃƒâ€Ã‚Â±tlÃƒâ€Ã‚Â± tÃƒÆ’Ã‚Â¼r bulunamadÃƒâ€Ã‚Â±.")
        
    def normalize_name(n):
        n = unicodedata.normalize('NFKD', n).encode('ASCII', 'ignore').decode('utf-8')
        return n.lower().replace(" ", "_").replace("-", "_")

    matched = 0
    covers_dir = get_covers_dir()
    os.makedirs(covers_dir, exist_ok=True)
    
    for g in genres:
        g_name = normalize_name(g["name"])
        match_url = None
        for f in files:
            f_name = normalize_name(os.path.splitext(f.get("name", ""))[0])
            if f_name == g_name or f_name.replace("_", "") == g_name.replace("_", ""):
                match_url = f.get("download_url")
                break
                
        if match_url:
            try:
                img_data = requests.get(match_url, timeout=10).content
                ext = os.path.splitext(match_url)[1] or ".jpg"
                local_path = os.path.join(covers_dir, f"genre_gh_{g['id']}{ext}")
                with open(local_path, "wb") as f_img:
                    f_img.write(img_data)
                db.update_genre(g["id"], g["name"], g.get("color"), f"/covers/genre_gh_{g['id']}{ext}")
                matched += 1
            except:
                pass
                
    return ok({"matched": matched})

@app.route("/api/genres/<int:genre_id>/cover", methods=["POST"])
def genres_upload_cover(genre_id):
    """TÃƒÆ’Ã‚Â¼r kapaÃƒâ€Ã…Â¸Ãƒâ€Ã‚Â± yÃƒÆ’Ã‚Â¼kle ve DB'ye cover_path kaydet."""
    if "file" not in request.files:
        return err("Dosya bulunamadÃƒâ€Ã‚Â±", 400)
    f = request.files["file"]
    if not f.filename:
        return err("Dosya adÃƒâ€Ã‚Â± boÃƒâ€¦Ã…Â¸", 400)
    covers_dir = get_covers_dir()
    os.makedirs(covers_dir, exist_ok=True)
    ext = os.path.splitext(f.filename)[1].lower() or ".jpg"
    fname = f"genre_{genre_id}{ext}"
    save_path = os.path.join(covers_dir, fname)
    f.save(save_path)
    db.update_genre(genre_id, name=db.get_all_genres_dict().get(genre_id, {}).get("name", ""), cover_path=f"/covers/{fname}")
    return ok({"cover_path": f"/covers/{fname}"})

