@app.route("/api/system_paths", methods=["PUT"])
@require_json
def system_paths_update():
    from _paths import get_project_root, is_frozen
    import os, sys
    body = request.get_json()
    
    def write_cfg(filename, path_val):
        if is_frozen():
            cfg_file = os.path.join(os.path.dirname(sys.executable), filename)
        else:
            cfg_file = os.path.join(get_project_root(), filename)
            
        if path_val and path_val.strip():
            with open(cfg_file, "w", encoding="utf-8") as f:
                f.write(path_val.strip())
        else:
            if os.path.isfile(cfg_file):
                os.remove(cfg_file)
                
    if "db_path" in body:
        write_cfg("db_path.cfg", body["db_path"])
    if "backup_path" in body:
        write_cfg("backup_path.cfg", body["backup_path"])
    if "covers_path" in body:
        write_cfg("covers_path.cfg", body["covers_path"])
        
    return ok({"message": "Paths updated successfully"})

