@app.route("/api/settings", methods=["PUT"])
@require_json
def settings_update():
    body = request.get_json()
    for key, val in body.items():
        db.set_setting(key, str(val))
    
    # Broadcast reload_settings to all clients
    clients = db.get_all_clients()
    for c in clients:
        hostname = c.get("hostname")
        if hostname:
            cmd_push(hostname, {"command": "reload_settings"})
            
    return ok()

@app.route("/api/settings/startup", methods=["POST"])
@require_json
def settings_startup():
    body = request.get_json()
    enable = body.get("enable", False)
    import subprocess
    startup_folder = os.path.join(os.environ.get("APPDATA", ""), "Microsoft", "Windows", "Start Menu", "Programs", "Startup")
    shortcut_path = os.path.join(startup_folder, "GameCenterServer.lnk")

    if enable:
        if getattr(sys, "frozen", False):
            target = os.path.abspath(sys.executable)
        else:
            bat_path = os.path.normpath(os.path.join(os.path.dirname(__file__), "..", "start_server.bat"))
            if os.path.isfile(bat_path):
                target = os.path.abspath(bat_path)
            else:
                target = os.path.abspath(sys.executable)
        
        ps_cmd = (
            f'$s = (New-Object -ComObject WScript.Shell).CreateShortcut("{shortcut_path}"); '
            f'$s.TargetPath = "{target}"; '
            f'$s.WorkingDirectory = "{os.path.dirname(target)}"; '
            f'$s.Save()'
        )
        try:
            subprocess.run(["powershell", "-Command", ps_cmd], capture_output=True, text=True, check=True)
            db.set_setting("startup_run", "true")
        except Exception as e:
            return err(f"Startup shortcut error: {e}", 500)
    else:
        if os.path.exists(shortcut_path):
            try:
                os.remove(shortcut_path)
                db.set_setting("startup_run", "false")
            except Exception as e:
                return err(f"Startup shortcut remove error: {e}", 500)
        else:
            db.set_setting("startup_run", "false")
            
    return ok({"message": "Startup setting updated", "enabled": enable})

@app.route("/api/settings/config_paths", methods=["POST"])
def settings_config_paths():
    body = request.get_json()
    db_path_val = body.get("db_path")
    backup_path_val = body.get("backup_path")
    
    cfg_base = os.path.dirname(sys.executable) if getattr(sys, "frozen", False) else get_project_root()
    
    if db_path_val is not None:
        if not db_path_val.strip():
            p = os.path.join(cfg_base, "db_path.cfg")
            if os.path.exists(p): os.remove(p)
        else:
            try:
                os.makedirs(db_path_val.strip(), exist_ok=True)
                with open(os.path.join(cfg_base, "db_path.cfg"), "w", encoding="utf-8") as f:
                    f.write(db_path_val.strip())
            except Exception as e:
                return err(f"DB Path error: {e}")
                
    if backup_path_val is not None:
        if not backup_path_val.strip():
            p = os.path.join(cfg_base, "backup_path.cfg")
            if os.path.exists(p): os.remove(p)
        else:
            try:
                os.makedirs(backup_path_val.strip(), exist_ok=True)
                with open(os.path.join(cfg_base, "backup_path.cfg"), "w", encoding="utf-8") as f:
                    f.write(backup_path_val.strip())
            except Exception as e:
                return err(f"Backup Path error: {e}")
                
    return ok()

