@app.route("/api/utils/list_dirs", methods=["GET"])
def utils_list_dirs():
    path = request.args.get("path", "")
    if not path:
        import string
        from ctypes import windll
        drives = []
        bitmask = windll.kernel32.GetLogicalDrives()
        for letter in string.ascii_uppercase:
            if bitmask & 1:
                drives.append(f"{letter}:\\")
            bitmask >>= 1
        return ok({"current": "", "dirs": [{"name": d, "path": d} for d in drives]})
        
    try:
        dirs = []
        for entry in os.scandir(path):
            if entry.is_dir() and not entry.name.startswith('$'):
                dirs.append({"name": entry.name, "path": entry.path})
        dirs.sort(key=lambda x: x["name"].lower())
        
        parent = os.path.dirname(path) if os.path.dirname(path) != path else ""
        if len(path) == 3 and path.endswith(":\\"): 
            parent = ""
            
        return ok({"current": path, "parent": parent, "dirs": dirs})
    except Exception as e:
        return err(str(e))

@app.route("/api/utils/list_files", methods=["GET"])
def utils_list_files():
    path = request.args.get("path", "")
    if not path or not os.path.isdir(path):
        return ok({"files": []})
        
    try:
        files = []
        for entry in os.scandir(path):
            if entry.is_file():
                ext = os.path.splitext(entry.name)[1].lower()
                files.append({"name": entry.name, "path": entry.path, "ext": ext})
        files.sort(key=lambda x: x["name"].lower())
        return ok({"files": files})
    except Exception as e:
        return err(str(e))

@app.route("/api/utils/translate", methods=["POST"])
@require_json
def utils_translate():
    data = request.json
    text = data.get("text", "")
    if not text:
        return ok({"translated": ""})
    try:
        url = "https://translate.googleapis.com/translate_a/single"
        params = {"client": "gtx", "sl": "auto", "tl": "tr", "dt": "t", "q": text}
        resp = requests.get(url, params=params, timeout=10)
        if resp.status_code == 200:
            res_data = resp.json()
            translated = "".join([t[0] for t in res_data[0]])
            return ok({"translated": translated})
        return ok({"translated": text})
    except Exception as e:
        print("Translate Error:", e)
        return ok({"translated": text})

