@app.route("/api/settings/system_backups", methods=["DELETE"])
def system_backups_delete():
    from _paths import get_backup_dir
    filename = request.args.get("filename")
    if not filename:
        return err("Dosya adÃƒâ€Ã‚Â± belirtilmedi")
    
    backup_dir = get_backup_dir()
    fpath = os.path.join(backup_dir, filename)
    
    if os.path.isfile(fpath):
        try:
            os.remove(fpath)
            return ok({"message": "Silindi"})
        except Exception as e:
            return err(str(e))
    return err("Dosya bulunamadÃƒâ€Ã‚Â±")

@app.route("/api/client_ip_status", methods=["GET"])
def client_ip_status():
    client_ip = request.remote_addr
    allowed_ips_str = db.get_setting("remote_play_allowed_ips", "")
    ips = [ip.strip() for ip in allowed_ips_str.split(",") if ip.strip()]
    return ok({
        "ip": client_ip,
        "is_allowed": client_ip in ips or client_ip in ("127.0.0.1", "::1")
    })

@app.route("/api/settings/allow_remote_play_ip", methods=["POST"])
def allow_remote_play_ip():
    client_ip = request.remote_addr
    allowed_ips_str = db.get_setting("remote_play_allowed_ips", "")
    ips = [ip.strip() for ip in allowed_ips_str.split(",") if ip.strip()]
    if client_ip not in ips and client_ip not in ("127.0.0.1", "::1"):
        ips.append(client_ip)
        db.set_setting("remote_play_allowed_ips", ",".join(ips))
    return ok({"ip": client_ip, "message": "IP added to allowed list"})

