@app.route("/api/activity", methods=["GET"])
def activity_list():
    try:
        page = int(request.args.get("page", 1))
        limit = int(request.args.get("limit", 20))
        query = request.args.get("query", "")
        start_date = request.args.get("start_date", "")
        end_date = request.args.get("end_date", "")
        offset = (page - 1) * limit
        return ok(db.get_activity_logs(limit, offset, query, start_date if start_date else None, end_date if end_date else None))
    except Exception as e:
        return ok(db.get_activity_logs(20, 0, ""))

@app.route("/api/activity/stats", methods=["GET"])
def activity_stats():
    return ok(db.get_activity_stats())

@app.route("/api/activity/bulk", methods=["DELETE"])
def activity_bulk_delete():
    before_date = request.args.get("before_date", "")
    db.delete_logs_bulk(before_date if before_date else None)
    return ok({"message": "Loglar silindi."})

@app.route("/api/activity", methods=["POST"])
@require_json
def activity_add():
    body = request.get_json()
    username = body.get("username", "Unknown")
    action = body.get("action", "play")
    details = body.get("details", "")

    # game_start / game_stop iÃƒÆ’Ã‚Â§in duplicate koruma (30 saniye cooldown)
    # AynÃƒâ€Ã‚Â± client + action 30 saniye iÃƒÆ’Ã‚Â§inde tekrar gelirse ignore et
    if action in ("game_start", "game_stop"):
        import time
        cache_key = f"{username}:{action}"
        now = time.time()
        last_time = _activity_cooldown_cache.get(cache_key, 0)
        if (now - last_time) < 30:
            return ok()  # Cooldown iÃƒÆ’Ã‚Â§inde ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â sessizce yoksay
        _activity_cooldown_cache[cache_key] = now

    db.add_activity_log(username, action, details)
    return ok()

