@app.route("/api/stats/top_games", methods=["GET"])
def stats_top_games():
    limit = int(request.args.get("limit", 10))
    top_games = db.get_top_games_by_clicks(limit)
    for g in top_games:
        g['game_name'] = g.get('name', 'Bilinmeyen Oyun')
    return ok(top_games)

