@app.route("/api/upload/cover", methods=["POST"])
def upload_cover():
    if "file" not in request.files:
        return err("Dosya bulunamadi")
    f = request.files["file"]
    ext = os.path.splitext(f.filename)[1].lower()
    if ext not in (".jpg", ".jpeg", ".png", ".webp"):
        return err("Gecersiz dosya turu")
    from _paths import get_app_dir, get_project_root
    covers_dir = get_covers_dir()
    os.makedirs(covers_dir, exist_ok=True)
    fname = f"{uuid.uuid4().hex}{ext}"
    f.save(os.path.join(covers_dir, fname))
    return ok({"filename": fname}, status=201)

@app.route("/api/games/upload_reg", methods=["POST"])
def upload_reg():
    directory = request.form.get("directory", "").strip()
    if not directory:
        return err("Oyun dizini belirtilmedi")
        
    try:
        reg_dir = os.path.join(directory, "reg")
        os.makedirs(reg_dir, exist_ok=True)
        
        if "reg_content" in request.form:
            content = request.form.get("reg_content")
            filename = request.form.get("filename", "custom.reg")
            safe_name = "".join([c if c.isalnum() or c in " .-_" else "_" for c in filename])
            target_path = os.path.join(reg_dir, safe_name)
            with open(target_path, "w", encoding="utf-8") as f:
                f.write(content)
            return ok({"message": "Reg kodu baÃƒâ€¦Ã…Â¸arÃƒâ€Ã‚Â±yla kaydedildi", "path": target_path})
            
        elif "file" in request.files:
            f = request.files["file"]
            if not f.filename.lower().endswith(".reg"):
                return err("Sadece .reg dosyalarÃƒâ€Ã‚Â± yÃƒÆ’Ã‚Â¼klenebilir")
            safe_name = "".join([c if c.isalnum() or c in " .-_" else "_" for c in f.filename])
            target_path = os.path.join(reg_dir, safe_name)
            f.save(target_path)
            return ok({"message": "Reg dosyasÃƒâ€Ã‚Â± baÃƒâ€¦Ã…Â¸arÃƒâ€Ã‚Â±yla yÃƒÆ’Ã‚Â¼klendi", "path": target_path})
            
        return err("Dosya veya kod bulunamadÃƒâ€Ã‚Â±")
    except Exception as e:
        return err(str(e))

@app.route("/api/static", methods=["GET"])
def api_static():
    path = request.args.get("path")
    if not path or not os.path.exists(path):
        return "Not found", 404
    from flask import send_file
    return send_file(path)

@app.route("/covers/<path:filename>")
def serve_cover(filename):
    covers_dir = get_covers_dir()
    full_path = os.path.join(covers_dir, filename)
    if not os.path.isfile(full_path):
        app.logger.warning(f"[COVER 404] Dosya bulunamadi: {full_path} | covers_dir={covers_dir}")
        return "", 404
    return send_from_directory(covers_dir, filename)

@app.route("/api/covers/<int:game_id>")
def serve_cover_by_game_id(game_id):
    """Oyun id'sine gÃƒÆ’Ã‚Â¶re kapak gÃƒÆ’Ã‚Â¶rselini dÃƒÆ’Ã‚Â¶ndÃƒÆ’Ã‚Â¼rÃƒÆ’Ã‚Â¼r."""
    game = db.get_game_by_id(game_id)
    if not game:
        return "Not Found", 404
    cover_path = game.get("cover_path", "")
    if not cover_path:
        return "No Cover", 404
    # cover_path "/covers/filename.jpg" formatÃƒâ€Ã‚Â±nda geliyor
    filename = os.path.basename(cover_path)
    covers_dir = get_covers_dir()
    full_path = os.path.join(covers_dir, filename)
    if not os.path.isfile(full_path):
        return "Not Found", 404
    return send_file(full_path)


@app.route("/api/icons/<path:filename>")
def serve_icons(filename):
    from _paths import get_icons_dir
    from flask import send_file
    import os
    
    icon_dir = get_icons_dir()
    path = os.path.normpath(os.path.join(icon_dir, filename.lstrip("/\\")))
    if os.path.exists(path):
        return send_file(path)
    return "Not Found", 404

