@app.route("/api/save_dirs", methods=["GET"])
def save_dirs_list():
    return ok(db.get_all_save_dirs())

@app.route("/api/save_dirs", methods=["POST"])
@require_json
def save_dirs_create():
    body = request.get_json()
    sid = db.create_save_dir(body.get("game_id"), body.get("save_path"), body.get("description", ""))
    return ok({"id": sid}, status=201)

@app.route("/api/save_dirs/<int:sd_id>", methods=["PUT"])
@require_json
def save_dirs_update(sd_id):
    body = request.get_json()
    db.update_save_dir(sd_id, body.get("save_path"), body.get("description", ""))
    return ok()

@app.route("/api/save_dirs/<int:sd_id>", methods=["DELETE"])
def save_dirs_delete(sd_id):
    db.delete_save_dir(sd_id)
    return ok()

