@app.route("/api/backups", methods=["GET"])
def backups_list():
    game_id = request.args.get("game_id")
    username = request.args.get("username")
    return ok(db.get_backups(game_id=game_id, username=username))

@app.route("/api/backups", methods=["POST"])
def backups_create():
    game_id = request.form.get("game_id", type=int)
    username = request.form.get("username", "")
    label = request.form.get("label", "")
    
    if not game_id or not username:
        return err("game_id ve username zorunludur", 400)
        
    f = request.files.get("file")
    if not f:
        return err("Dosya yÃƒÆ’Ã‚Â¼klenmedi", 400)
        
    # DosyayÃƒâ€Ã‚Â± kaydet
    from _paths import get_backup_dir
    backup_dir = get_backup_dir()
    os.makedirs(backup_dir, exist_ok=True)
    
    import uuid
    filename = f"{game_id}_{username}_{uuid.uuid4().hex[:8]}.zip"
    filepath = os.path.join(backup_dir, filename)
    f.save(filepath)
    size_bytes = os.path.getsize(filepath)
    
    bid = db.create_backup(game_id, username, filepath, label, size_bytes)
    return ok({"id": bid}, status=201)

@app.route("/api/backups/<int:bid>", methods=["DELETE"])
def backups_delete(bid):
    backup = db.get_backup_by_id(bid)
    if backup:
        path = backup.get("backup_path", "")
        if path and os.path.exists(path):
            try:
                os.remove(path)
            except:
                pass
    db.delete_backup(bid)
    return ok()

