@app.route("/api/backups/<int:bid>/restore", methods=["POST"])
def backups_restore(bid):
    """Backup ZIP dosyasini indir."""
    import io
    backup = db.get_backup_by_id(bid)
    if not backup:
        return err("Backup bulunamadi", 404)
    file_path = backup.get("backup_path", "")
    if not file_path or not os.path.isfile(file_path):
        return err("Backup dosyasi bulunamadi", 404)
    from flask import send_file
    return send_file(file_path, as_attachment=True,
                     download_name=os.path.basename(file_path))

