@app.route("/api/network/report", methods=["POST"])
def network_report():
    """Client aÃƒâ€Ã…Â¸ istatistiÃƒâ€Ã…Â¸i gÃƒÆ’Ã‚Â¶nderir (heartbeat ile)."""
    d = request.get_json(force=True, silent=True) or {}
    hostname     = d.get("hostname", "unknown")
    dl_kbps      = float(d.get("download_kbps", 0))
    ul_kbps      = float(d.get("upload_kbps",   0))
    dl_mb        = float(d.get("download_mb",   0))
    ul_mb        = float(d.get("upload_mb",     0))
    db.record_network(hostname, dl_kbps, ul_kbps, dl_mb, ul_mb)
    return ok()


@app.route("/api/network/history", methods=["GET"])
def network_history():
    """Belirli host iÃƒÆ’Ã‚Â§in veya tÃƒÆ’Ã‚Â¼m aÃƒâ€Ã…Â¸ iÃƒÆ’Ã‚Â§in (aggregate) geÃƒÆ’Ã‚Â§miÃƒâ€¦Ã…Â¸ verisi."""
    hostname = request.args.get("hostname", "")
    hours    = int(request.args.get("hours", 24))
    if hostname:
        if hours > 24:
            with db.get_connection() as conn:
                rows = conn.execute(
                    "SELECT strftime('%Y-%m-%d %H:00', recorded_at) as hour, "
                    "AVG(download_kbps) as avg_dl, AVG(upload_kbps) as avg_ul "
                    "FROM network_history "
                    "WHERE hostname = ? AND recorded_at >= datetime('now', ?, 'localtime') "
                    "GROUP BY hour ORDER BY hour ASC",
                    (hostname, f"-{hours} hours")
                ).fetchall()
                data = []
                for r in rows:
                    data.append({
                        "recorded_at": r["hour"] + ":00",
                        "download_mbps": round((r["avg_dl"] * 8) / 1024, 2) if r["avg_dl"] else 0,
                        "upload_mbps": round((r["avg_ul"] * 8) / 1024, 2) if r["avg_ul"] else 0
                    })
                return ok(data)
        else:
            data = db.get_network_history(hostname, hours)
            for d in data:
                d["download_mbps"] = round((d.get("download_kbps", 0) * 8) / 1024, 2)
                d["upload_mbps"] = round((d.get("upload_kbps", 0) * 8) / 1024, 2)
            return ok(data)
    
    # Aggregate (All hosts)
    if hours > 24:
        with db.get_connection() as conn:
            rows = conn.execute(
                "SELECT strftime('%Y-%m-%d %H:00', recorded_at) as hour, "
                "SUM(download_kbps) as total_dl, SUM(upload_kbps) as total_ul "
                "FROM network_history "
                "WHERE recorded_at >= datetime('now', ?, 'localtime') "
                "GROUP BY hour ORDER BY hour ASC",
                (f"-{hours} hours",)
            ).fetchall()
            data = []
            for r in rows:
                data.append({
                    "recorded_at": r["hour"] + ":00",
                    "download_mbps": round((r["total_dl"] * 8) / 1024, 2) if r["total_dl"] else 0,
                    "upload_mbps": round((r["total_ul"] * 8) / 1024, 2) if r["total_ul"] else 0
                })
            return ok(data)
    else:
        with db.get_connection() as conn:
            rows = conn.execute(
                "SELECT strftime('%Y-%m-%d %H:%M', recorded_at) as minute, "
                "SUM(download_kbps) as total_dl, SUM(upload_kbps) as total_ul "
                "FROM network_history "
                "WHERE recorded_at >= datetime('now', ?, 'localtime') "
                "GROUP BY minute ORDER BY minute ASC",
                (f"-{hours} hours",)
            ).fetchall()
            data = []
            for r in rows:
                data.append({
                    "recorded_at": r["minute"] + ":00",
                    "download_mbps": round((r["total_dl"] * 8) / 1024, 2) if r["total_dl"] else 0,
                    "upload_mbps": round((r["total_ul"] * 8) / 1024, 2) if r["total_ul"] else 0
                })
            return ok(data)


@app.route("/api/network/hosts", methods=["GET"])
def network_hosts():
    """TÃƒÆ’Ã‚Â¼m istemci bilgisayarlarÃƒâ€Ã‚Â± aÃƒâ€Ã…Â¸ sayfasÃƒâ€Ã‚Â± iÃƒÆ’Ã‚Â§in dÃƒÆ’Ã‚Â¶ndÃƒÆ’Ã‚Â¼r (indirme/yÃƒÆ’Ã‚Â¼kleme hÃƒâ€Ã‚Â±zlarÃƒâ€Ã‚Â±yla)."""
    clients = db.get_all_clients()
    latest_net = db.get_network_latest()
    net_map = {row["hostname"]: row for row in latest_net}
    
    from datetime import datetime
    now = datetime.now()
    
    for c in clients:
        hname = c.get("hostname", "")
        # Determine if online
        last_seen_str = c.get("last_seen")
        is_online = False
        if last_seen_str:
            try:
                ls_time = datetime.strptime(last_seen_str, "%Y-%m-%d %H:%M:%S")
                diff = (now - ls_time).total_seconds()
                if diff <= 120:
                    is_online = True
            except:
                pass
        c["is_online"] = is_online
        
        if hname in net_map:
            c["download_mbps"] = round((net_map[hname].get("download_kbps", 0) * 8) / 1024, 2)
            c["upload_mbps"] = round((net_map[hname].get("upload_kbps", 0) * 8) / 1024, 2)
        else:
            c["download_mbps"] = 0
            c["upload_mbps"] = 0
            
    return ok(clients)


@app.route("/api/network/latest", methods=["GET"])
def network_latest():
    """TÃƒÆ’Ã‚Â¼m aÃƒâ€Ã…Â¸Ãƒâ€Ã‚Â±n anlÃƒâ€Ã‚Â±k toplam bant geniÃƒâ€¦Ã…Â¸liÃƒâ€Ã…Â¸i durumunu dÃƒÆ’Ã‚Â¶ndÃƒÆ’Ã‚Â¼r."""
    rows = db.get_network_latest()
    total_dl = sum(r.get("download_kbps", 0) for r in rows)
    total_ul = sum(r.get("upload_kbps", 0) for r in rows)
    return ok({
        "download_mbps": round((total_dl * 8) / 1024, 2),
        "upload_mbps":   round((total_ul * 8) / 1024, 2),
        "active_connections": len(rows)
    })




