@app.route('/api/logs', methods=['GET'])
def get_logs():
    """Sunucu log dosyasÃƒâ€Ã‚Â±ndan son 200 satÃƒâ€Ã‚Â±rÃƒâ€Ã‚Â± okur."""
    lines_count = 200
    try:
        log_file_path = os.path.join(os.path.dirname(__file__), 'logs', 'server.log')
        if not os.path.exists(log_file_path):
            return jsonify({"status": "ok", "data": ["Log dosyasÃƒâ€Ã‚Â± henÃƒÆ’Ã‚Â¼z oluÃƒâ€¦Ã…Â¸turulmadÃƒâ€Ã‚Â±."]})
        
        with open(log_file_path, 'r', encoding='utf-8') as f:
            lines = f.readlines()
            last_lines = lines[-lines_count:]
            
        return jsonify({"status": "ok", "data": [line.strip() for line in last_lines]})
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 500

# ────────────────── STEAM ACCOUNTS ────────────────────────────────────────────────
@app.route('/api/steam', methods=['GET'])
def get_steam_accounts():
    with db.get_connection() as conn:
        # Otomatik temizlik: 2 dakikadan uzun süredir haber alınamayan masaların hesaplarını boşa çıkar
        conn.execute("""
            UPDATE steam_accounts 
            SET is_in_use = 0, in_use_by = '' 
            WHERE is_in_use = 1 
              AND in_use_by IN (
                SELECT hostname FROM clients 
                WHERE last_seen < datetime('now', 'localtime', '-2 minutes')
              )
        """)
        conn.commit()
        rows = conn.execute("SELECT id, title, username, password, is_in_use, in_use_by, games FROM steam_accounts").fetchall()
    allow = db.get_setting("allow_client_steam_checkout", "1") == "1"
    return ok({"accounts": [dict(r) for r in rows], "allow_checkout": allow})

def get_steam_info_from_games():
    """Oyun arsivi tablosundan Steam'in yolunu ve parametrelerini bulur"""
    with db.get_connection() as conn:
        game = conn.execute("SELECT directory, executable, launch_params FROM games WHERE lower(name) = 'steam' OR lower(executable) = 'steam.exe' LIMIT 1").fetchone()
        if game:
            directory = (game["directory"] or "").rstrip('\\').rstrip('/')
            executable = (game["executable"] or "").lstrip('\\').lstrip('/')
            path = f"{directory}\\{executable}" if directory and executable else executable
            return path, game["launch_params"] or ""
    return "", ""

@app.route('/api/steam/reserve', methods=['POST'])
def reserve_steam_account():
    body = request.get_json() or {}
    account_id = body.get("account_id")
    if not account_id:
        return err("Account ID gerekli")
    
    with db.get_connection() as conn:
        acc = conn.execute("SELECT is_in_use, in_use_by FROM steam_accounts WHERE id=?", (account_id,)).fetchone()
        if not acc:
            return err("Hesap bulunamadi", 404)
        if acc["is_in_use"] and acc["in_use_by"] != body.get("hostname", body.get("username", "")):
            return err("Bu hesap su an baska bir kullanici tarafindan kullanimda", 400)
            
        conn.execute("UPDATE steam_accounts SET is_in_use=1, in_use_by=?, last_used=datetime('now', 'localtime') WHERE id=?", (body.get("hostname", body.get("username", "")), account_id))
    
    steam_path, steam_params = get_steam_info_from_games()
    if not steam_path:
        # Steam oyun arşivinde yoksa kaydı geri al ve hata ver
        with db.get_connection() as conn:
            conn.execute("UPDATE steam_accounts SET is_in_use=0, in_use_by='' WHERE id=?", (account_id,))
        return err("Bu oyun arşivinde Steam bulunamadı. Lütfen yöneticiye bildirin.", 400)

    login_method = db.get_setting("steam_login_method", "keyboard")
    return ok({"message": "Hesap rezerve edildi", "success": True, "steam_path": steam_path, "steam_params": steam_params, "steam_login_method": login_method})

@app.route('/api/steam/release', methods=['POST'])
def release_steam_account():
    body = request.get_json() or {}
    account_id = body.get("account_id")
    req_user = body.get("username", "")
    req_host = body.get("hostname", "")
    with db.get_connection() as conn:
        if account_id:
            conn.execute("UPDATE steam_accounts SET is_in_use=0, in_use_by='' WHERE id=? AND (in_use_by=? OR in_use_by=?)", (account_id, req_user, req_host))
        else:
            conn.execute("UPDATE steam_accounts SET is_in_use=0, in_use_by='' WHERE in_use_by=? OR in_use_by=?", (req_user, req_host))
    return ok({"message": "Hesap(lar) serbest birakildi"})

@app.route('/api/admin/steam', methods=['POST'])
def add_steam_account():
    body = request.get_json() or {}
    title    = body.get("title", "").strip()
    username = body.get("username", "").strip()
    password = body.get("password", "")
    games    = body.get("games", "").strip()
    platform = body.get("platform", "steam").strip() or "steam"
    extra_params = body.get("extra_params", "{}")
    if not title or not username or not password:
        return err("Eksik bilgi")
    try:
        with db.get_connection() as conn:
            conn.execute(
                "INSERT INTO steam_accounts (title, username, password, games, platform, extra_params) VALUES (?, ?, ?, ?, ?, ?)",
                (title, username, password, games, platform, extra_params)
            )
        return ok({"message": "Eklendi"})
    except sqlite3.IntegrityError:
        return err("Bu kullanici adi zaten ekli", 400)

