@app.route('/api/admin/steam/<int:acc_id>/assign', methods=['POST'])
def assign_steam_account(acc_id):
    body = request.get_json() or {}
    hostname = body.get("hostname")
    if not hostname:
        return err("hostname gerekli", 400)

    try:
        with db.get_connection() as conn:
            client = conn.execute("SELECT (strftime('%s', 'now', 'localtime') - strftime('%s', last_seen)) as diff FROM clients WHERE hostname=?", (hostname,)).fetchone()
            if not client or client["diff"] is None or client["diff"] > 60:
                return err("SeÃƒÆ’Ã‚Â§ilen bilgisayar Ãƒâ€¦Ã…Â¸u an ÃƒÆ’Ã‚Â§evrimdÃƒâ€Ã‚Â±Ãƒâ€¦Ã…Â¸Ãƒâ€Ã‚Â± (kapalÃƒâ€Ã‚Â±).", 400)

            acc = conn.execute("SELECT * FROM steam_accounts WHERE id=?", (acc_id,)).fetchone()
            if not acc:
                return err("Hesap bulunamadi", 404)
            conn.execute(
                "UPDATE steam_accounts SET is_in_use=1, in_use_by=?, last_used=datetime('now', 'localtime') WHERE id=?",
                (hostname, acc_id)
            )

        acc_dict = dict(acc)
        platform     = acc_dict.get("platform") or "steam"
        extra_params = acc_dict.get("extra_params") or "{}"

        login_method = db.get_setting("steam_login_method", "keyboard")

        # Geriye dÃƒÆ’Ã‚Â¶nÃƒÆ’Ã‚Â¼k uyumluluk ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â eski steam_login komutu
        if platform == "steam":
            cmd_push(hostname, {
                "command": "steam_login",
                "username": acc_dict["username"],
                "password": acc_dict["password"],
                "steam_login_method": login_method
            })

        # Yeni platform-agnostik komut
        cmd_push(hostname, {
            "command": "game_account_login",
            "platform": platform,
            "username": acc_dict["username"],
            "password": acc_dict["password"],
            "extra_params": extra_params,
            "steam_login_method": login_method
        })

        return ok({"message": f"{hostname} bilgisayarina gonderildi", "platform": platform})
    
    except Exception as e:
        import traceback
        with open("assign_err.txt", "w") as f:
            f.write(traceback.format_exc())
        return err(str(e), 500)

