@app.route('/api/updates/run/<int:pid>', methods=['POST'])

def run_update_now(pid):
    try:
        profile = db.get_update_profile(pid)
        if not profile:
            return jsonify({"status": "error", "message": "Profil bulunamadÃƒâ€Ã‚Â±"}), 404

        if um.is_running(pid):
            return jsonify({"status": "error", "message": "GÃƒÆ’Ã‚Â¼ncelleme zaten ÃƒÆ’Ã‚Â§alÃƒâ€Ã‚Â±Ãƒâ€¦Ã…Â¸Ãƒâ€Ã‚Â±yor"}), 409

        game_name = profile.get("game_name") or "Bilinmeyen Oyun"
        profile_name = profile.get("name") or ""
        log_id = db.create_update_log(pid, game_name, profile_name, triggered_by="manual")

        with _update_lock:
            _update_outputs[log_id] = ""

        def on_output(line):
            with _update_lock:
                _update_outputs[log_id] = _update_outputs.get(log_id, "") + line
            socketio.emit("update_log", {"log_id": log_id, "line": line})

        def on_done(success, full_output):
            db.finish_update_log(log_id, success, full_output)
            socketio.emit("update_done", {"log_id": log_id, "success": success})

        um.run_update(profile, on_output=on_output, on_done=on_done)

        return jsonify({"status": "ok", "log_id": log_id})
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 500


