@app.route('/api/monitor/clients', methods=['GET'])
def monitor_get_clients_api():
    import json as _json
    clients = db.get_clients_with_monitor()
    for c in clients:
        profile_osd = c.get('profile_osd', {})
        current_osd = c.get('current_osd', {})

        if c.get('monitor_profile_id') and c.get('disp_reported_at') and profile_osd and current_osd:
            # Profildeki her VCP kodunun mevcut değerle eşleşip eşleşmediğini kontrol et
            mismatches = [
                k for k, v in profile_osd.items()
                if k in current_osd and current_osd[k] != v
            ]
            c['match_status'] = 'match' if not mismatches else 'mismatch'
            c['mismatch_keys'] = mismatches
        elif c.get('monitor_profile_id'):
            c['match_status'] = 'unknown'
            c['mismatch_keys'] = []
        else:
            c['match_status'] = 'no_profile'
            c['mismatch_keys'] = []
    return jsonify({"status": "ok", "data": clients})


