@app.route('/api/monitor/force-apply/<hostname>', methods=['POST'])
def monitor_force_apply(hostname):
    with db.get_connection() as conn:
        client = conn.execute("SELECT monitor_profile_id FROM clients WHERE hostname=?", (hostname,)).fetchone()
        if not client or not client['monitor_profile_id']:
            return jsonify({"status": "error", "message": "Bu PC'ye profil atanmamis"}), 400
        conn.execute("UPDATE clients SET pending_monitor_apply=1 WHERE hostname=?", (hostname,))
        profile = conn.execute(
            "SELECT mp.name FROM clients c JOIN monitor_profiles mp ON mp.id=c.monitor_profile_id WHERE c.hostname=?",
            (hostname,)
        ).fetchone()
        pname = profile['name'] if profile else ''
        conn.execute(
            "INSERT INTO monitor_apply_log (hostname, action, profile_name, detail) VALUES (?,?,?,?)",
            (hostname, 'force_apply_queued', pname, 'Admin panelinden anlik uygulama istendi')
        )
        conn.commit()
    return jsonify({"status": "ok"})


@app.route('/api/monitor/pending/<hostname>', methods=['GET'])
def monitor_get_pending(hostname):
    with db.get_connection() as conn:
        row = conn.execute("SELECT pending_monitor_apply FROM clients WHERE hostname=?", (hostname,)).fetchone()
    if not row:
        return jsonify({"pending": False})
    return jsonify({"pending": bool(row['pending_monitor_apply'])})


@app.route('/api/monitor/ack/<hostname>', methods=['POST'])
def monitor_ack(hostname):
    with db.get_connection() as conn:
        conn.execute("UPDATE clients SET pending_monitor_apply=0 WHERE hostname=?", (hostname,))
        profile = conn.execute(
            "SELECT mp.name FROM clients c JOIN monitor_profiles mp ON mp.id=c.monitor_profile_id WHERE c.hostname=?",
            (hostname,)
        ).fetchone()
        pname = profile['name'] if profile else ''
        conn.execute(
            "INSERT INTO monitor_apply_log (hostname, action, profile_name, detail) VALUES (?,?,?,?)",
            (hostname, 'applied', pname, 'Profil basariyla uygulandi')
        )
        conn.commit()
    return jsonify({"status": "ok"})


@app.route('/api/monitor/logs', methods=['GET'])
def monitor_get_logs():
    limit = int(request.args.get('limit', 100))
    with db.get_connection() as conn:
        rows = conn.execute(
            "SELECT * FROM monitor_apply_log ORDER BY id DESC LIMIT ?", (limit,)
        ).fetchall()
    return jsonify({"status": "ok", "data": [dict(r) for r in rows]})

# ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ GÃƒÆ’Ã‚Â¼ncelleme Zamanlama Thread'i ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬

def _update_scheduler_loop():
    """Her 60 saniyede bir schedule_enabled=1 profilleri kontrol eder."""
    import time
    from datetime import datetime as _dt
    triggered_today = set()  # (profile_id, date_str) ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ bugÃƒÆ’Ã‚Â¼n tetiklendi mi
    while True:
        try:
            now = _dt.now()
            today_key = now.strftime("%Y-%m-%d")
            current_hhmm = now.strftime("%H:%M")

            profiles = db.get_scheduled_profiles()
            for p in profiles:
                key = (p["id"], today_key)
                if p["schedule_time"] == current_hhmm and key not in triggered_today:
                    triggered_today.add(key)
                    logging.info(f"[Scheduler] {p['name']} profili tetikleniyor ({current_hhmm})")

                    game_name = p.get("game_name") or ""
                    log_id = db.create_update_log(p["id"], game_name, p["name"], triggered_by="schedule")

                    with _update_lock:
                        _update_outputs[log_id] = ""

                    def _make_callbacks(lid, profile):
                        def on_output(line):
                            with _update_lock:
                                _update_outputs[lid] = _update_outputs.get(lid, "") + line
                            socketio.emit("update_log", {"log_id": lid, "line": line})
                        def on_done(success, full_output):
                            db.finish_update_log(lid, success, full_output)
                            socketio.emit("update_done", {"log_id": lid, "success": success})
                        return on_output, on_done

                    oo, od = _make_callbacks(log_id, p)
                    um.run_update(p, on_output=oo, on_done=od)

            # Gece yarÃƒâ€Ã‚Â±sÃƒâ€Ã‚Â± eski kÃƒâ€Ã‚Â±yÃƒâ€Ã‚Â± key'leri temizle
            old_keys = {k for k in triggered_today if k[1] != today_key}
            for k in old_keys:
                triggered_today.discard(k)

        except Exception as exc:
            logging.error(f"[Scheduler] Hata: {exc}")

        time.sleep(60)


threading.Thread(target=_update_scheduler_loop, daemon=True).start()

# ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬


# ── GitHub Cloud Update API ──────────────────────────────────────────────────
import json as _json
import urllib.request as _urllib_req
import urllib.error as _urllib_err
import shutil as _shutil
import tempfile as _tempfile
import hashlib as _hashlib

GITHUB_REPO = "rcpdkc/game-center-server"
_update_state = {
    "status": "idle",       # idle | checking | downloading | applying | done | error
    "progress": 0,
    "latest_version": None,
    "current_version": None,
    "release_notes": "",
    "download_url": "",
    "asset_name": "",
    "error": "",
    "temp_file": None,
}
_update_lock = threading.Lock()

def _get_current_version():
    """server dizinindeki VERSION dosyasını ya da config'i oku."""
    from _paths import get_data_dir
    ver_file = os.path.join(get_data_dir(), "VERSION")
    if os.path.exists(ver_file):
        with open(ver_file, "r", encoding="utf-8") as f:
            return f.read().strip()
    return db.get_setting("server_version", "0.0.0")

def _version_tuple(v):
    try:
        return tuple(int(x) for x in str(v).lstrip("v").split("."))
    except Exception:
        return (0, 0, 0)

def _check_github_release():
    """GitHub API'yi sorgular, yeni sürüm varsa True döner."""
    url = f"https://api.github.com/repos/{GITHUB_REPO}/releases/latest"
    try:
        import requests
        import time
        max_retries = 3
        for attempt in range(max_retries):
            try:
                resp = requests.get(url, timeout=10, headers={"User-Agent": "GameCenter-Updater/1.0"})
                resp.raise_for_status()
                data = resp.json()
                tag = data.get("tag_name", "").lstrip("v")
                current = _get_current_version().lstrip("v")
                assets = data.get("assets", [])
                exe_asset = next((a for a in assets if a["name"].lower().endswith(".exe")), None)
                return {
                    "latest_version": tag,
                    "current_version": current,
                    "has_update": _version_tuple(tag) > _version_tuple(current),
                    "release_notes": data.get("body", ""),
                    "download_url": exe_asset["browser_download_url"] if exe_asset else "",
                    "asset_name": exe_asset["name"] if exe_asset else "",
                }
            except Exception as e:
                if attempt == max_retries - 1:
                    raise e
                time.sleep(2)
    except _urllib_err.URLError as e:
        raise RuntimeError(f"GitHub'a erişilemedi: {e.reason}")
    except Exception as e:
        raise RuntimeError(str(e))


@app.route("/api/system/update/check", methods=["GET"])
def api_update_check():
    try:
        info = _check_github_release()
        with _update_lock:
            _update_state["latest_version"] = info["latest_version"]
            _update_state["current_version"] = info["current_version"]
            _update_state["release_notes"] = info["release_notes"]
            _update_state["download_url"] = info["download_url"]
            _update_state["asset_name"] = info["asset_name"]
        return jsonify({"ok": True, **info})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500


@app.route("/api/system/update/status", methods=["GET"])
def api_update_status():
    with _update_lock:
        return jsonify(dict(_update_state))


@app.route("/api/system/update/apply", methods=["POST"])
def api_update_apply():
    with _update_lock:
        if _update_state["status"] in ("downloading", "applying"):
            return jsonify({"ok": False, "error": "Zaten bir güncelleme işlemi devam ediyor."}), 400
        download_url = _update_state.get("download_url", "")
        asset_name = _update_state.get("asset_name", "GameCenter_Setup.exe")
        if not download_url:
            return jsonify({"ok": False, "error": "İndirilecek dosya bulunamadı."}), 400
        _update_state["status"] = "downloading"
        _update_state["progress"] = 0
        _update_state["error"] = ""

    def _do_update():
        tmp_path = None
        try:
            import glob
            # 0. Önceden kalan tüm GameCenter_Setup*.exe dosyalarını temizle
            tmp_dir = _tempfile.gettempdir()
            old_files = glob.glob(os.path.join(tmp_dir, "GameCenter_Setup*.exe"))
            for old_f in old_files:
                try:
                    os.remove(old_f)
                    print(f"[Update] Eski kurulum dosyasi temizlendi: {old_f}")
                except Exception as e:
                    print(f"[Update] Eski dosya silinemedi: {old_f} - {e}")

            # 1. Geçici dosyaya indir
            tmp_dir = _tempfile.gettempdir()
            os.makedirs(tmp_dir, exist_ok=True)  # Temp\1\ gibi alt klasörler silinmişse yeniden oluştur
            tmp_path = os.path.join(tmp_dir, asset_name)
            with _update_lock:
                _update_state["temp_file"] = tmp_path

            import requests
            import time
            max_retries = 3
            for attempt in range(max_retries):
                try:
                    with requests.get(download_url, stream=True, timeout=30, headers={"User-Agent": "GameCenter-Updater/1.0"}) as resp:
                        resp.raise_for_status()
                        total = int(resp.headers.get("content-length", 0))
                        downloaded = 0
                        chunk_size = 65536
                        with open(tmp_path, "wb") as f:
                            for chunk in resp.iter_content(chunk_size=chunk_size):
                                if chunk:
                                    f.write(chunk)
                                    downloaded += len(chunk)
                                    if total > 0:
                                        pct = int(downloaded / total * 90)
                                        with _update_lock:
                                            _update_state["progress"] = pct
                    break # Success
                except Exception as e:
                    if attempt == max_retries - 1:
                        raise e
                    time.sleep(2)

            with _update_lock:
                _update_state["progress"] = 92
                _update_state["status"] = "applying"

            # 2. Silent kurulum başlat
            import subprocess
            subprocess.Popen(
                [tmp_path, "/VERYSILENT", "/NORESTART", "/SUPPRESSMSGBOXES"],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            
            # Sunucu Inno Setup tarafindan kapatilana kadar applying'de kalmali
            # Asla "done" yapmiyoruz, arayuz baglanti kopmasini bekleyecek!

        except Exception as exc:
            with _update_lock:
                _update_state["status"] = "error"
                _update_state["error"] = str(exc)
            # Geçici dosyayı temizle
            if tmp_path and os.path.exists(tmp_path):
                try:
                    os.remove(tmp_path)
                except Exception:
                    pass

    threading.Thread(target=_do_update, daemon=True).start()
    return jsonify({"ok": True, "message": "Güncelleme başlatıldı."})


@app.route("/api/system/update/cleanup", methods=["POST"])
def api_update_cleanup():
    """İndirilen geçici dosyayı sil, state'i sıfırla."""
    with _update_lock:
        tmp = _update_state.get("temp_file")
        _update_state.update({
            "status": "idle", "progress": 0, "error": "",
            "temp_file": None,
        })
    if tmp and os.path.exists(tmp):
        try:
            os.remove(tmp)
        except Exception:
            pass
    return jsonify({"ok": True})
