# ── AUTO UPDATER API ───────────────────────────────────────────────────────

if __name__ == "__main__":

    db.init_db()
    port = int(db.get_setting("server_port", "5174"))
    logging.info(f"Game Center Server baslatiliyor -> http://0.0.0.0:{port}")

    # Cloud telemetri thread'ini baslat (Vercel'e 15dk'da bir veri gonderir)
    try:
        telemetry.start_telemetry_thread()
        logging.info("[Telemetry] Cloud telemetri thread'i baslatildi.")
    except Exception as _tel_err:
        logging.warning(f"[Telemetry] Thread baslatma hatasi: {_tel_err}")

    # Ebeveyn iÃƒâ€¦Ã…Â¸lem takibi (Orphaned process prevention)
    if "--parent-pid" in sys.argv:
        try:
            ppid_idx = sys.argv.index("--parent-pid")
            ppid = int(sys.argv[ppid_idx + 1])
            import psutil
            def watch_parent():
                while True:
                    try:
                        if not psutil.pid_exists(ppid):
                            logging.info("Parent process killed. Self-terminating.")
                            os._exit(0)
                    except Exception:
                        pass
                    time.sleep(2)
            t = threading.Thread(target=watch_parent, daemon=True)
            t.start()
        except Exception as e:
            logging.error(f"Error starting parent watcher: {e}")

    app.run(host="0.0.0.0", port=port, debug=False, threaded=True)
